from collections import Counter


def max_occurrences(nums):
    """Write a function to find the item with maximum frequency in a given list.

    Return a tuple ``(item, count)`` for the most frequent item.
    If multiple items share the maximum frequency, the one first
    encountered in ``nums`` is returned. An empty list returns
    ``(None, 0)``.
    """
    counts = Counter(nums)
    if not counts:
        return (None, 0)
    return counts.most_common(1)[0]
